// model/privacy.mjs -- notifications, URL redaction and the host settings file's container. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  QUOTE_OPEN, QUOTE_CLOSE, SEP, GLYPHS, NOTIFY_IDS
} from "./build.mjs"
import {
  str, asList, fnv1a32
} from "./text.mjs"
import {
  cleanName
} from "./channels.mjs"
import {
  mergeDropNotice, stateUnreadableNotice
} from "./state.mjs"
import {
  parseHelperStatus, entryInputNotice, ownedEntryPatch
} from "./settings.mjs"
import {
  helperArgv
} from "./mpv.mjs"
import {
  playerSeekArgv
} from "./rewind.mjs"
import {
  formatCount, pluralChannels, epgFields, formatEpgLine
} from "./epg.mjs"
import {
  rowDetail, rowAccessibleName
} from "./contrast.mjs"
import {
  resolveEpgUrl, sourceKey
} from "./sources.mjs"
import {
  removeSource, entryWith
} from "./source-records.mjs"

// ---- D-SINK-18: the container the host settings file is, before a URL goes
// into it.
//
// `persistActive` writes the active source's playlist and EPG URLs onto the
// plugin's bar entry and the host persists that into
// ~/.config/omarchy/shell.json. The lead MEASURED (2026-10-09) that the
// packaged default of that file is 0644, that `omarchy-refresh-config`
// copies it with `cp -f` (so a first creation under the ordinary umask leaves
// it 0644), and that Quickshell's FileView with `atomicWrites: true` neither
// resets nor tightens the mode of a file that already exists: 0644 in, 0644
// out, content changed. So the plugin cannot assume the file it is putting a
// provider credential into is private -- while its OWN files are 0600 inside
// 0700 directories (rule 6).
//
// The owner's ruling: make that one file private BEFORE the URL goes in, and
// REFUSE to persist if it cannot be made private. QML cannot chmod, so the
// work is the helper's `config shield` verb; these three functions are the
// decision, lifted here so a test can call it (rule 12) instead of a QML
// component holding it where nothing can reach it.
//
// Deliberately NOT widened: nothing here looks at, reports or acts on the
// mode of ~/.config or ~/.config/omarchy. A 0600 file is sufficient whatever
// the directory modes are, and ~/.config is shared with everything on the
// system.
var CONFIG_SHIELD_UNKNOWN = ""
var CONFIG_SHIELD_PRIVATE = "private"
var CONFIG_SHIELD_EXPOSED = "exposed"
// D-SINK-18, found by the review: everything that was not exactly "private"
// collapsed to "exposed", so an ABSENT settings file refused every save
// permanently. There is no file, so there is no credential in it and nothing
// to tighten; the host creates it on the write and the re-arm that follows
// every write tightens it then. Refusing instead made the plugin
// unconfigurable on a machine that simply had no user config yet.
var CONFIG_SHIELD_ABSENT = "absent"

var CONFIG_PERSIST = "persist"
var CONFIG_REFUSE = "refuse"
var CONFIG_DEFER = "defer"

function configShieldArgv(helperPath) {
  return helperArgv(helperPath, ["config", "shield"])
}

// The verb's answer, collapsed to the only distinction the service acts on.
//
// FAIL CLOSED, and that is the whole shape of this function: `private` is
// returned only when the run said so three ways at once -- `ok`, `private`
// and the verdict string. Everything else is `exposed`: a crashed helper, no
// output at all, an unparseable line, one of the verb's other verdicts
// (absent, symlink, foreign, not_regular, replaced, error) and -- the case
// this is really written for -- a verdict string this version of the model has
// never heard of. A helper that learns a new verdict later cannot have it
// read as "private" by an older guide.
//
// There is no "unknown" return. Unknown means "the run has not answered
// yet", which is a fact about the SERVICE and not about the file, and
// conflating the two is how a broken helper would come to defer every write
// for ever.
function configShieldState(text) {
  var status = parseHelperStatus(text, "config")
  if (status.ok === true && status.private === true && str(status.verdict) === CONFIG_SHIELD_PRIVATE) {
    return CONFIG_SHIELD_PRIVATE
  }
  // An absent file is its own answer and not an exposure. Everything else --
  // a symlink, a device, someone else's file, a failed chmod, an unreadable
  // reply -- still fails CLOSED to "exposed", because each of those means we
  // could not establish that the file is private.
  if (str(status.verdict) === CONFIG_SHIELD_ABSENT) return CONFIG_SHIELD_ABSENT
  return CONFIG_SHIELD_EXPOSED
}

// Does this persist put a secret into the file?
//
// ANY non-empty URL does. Not "does it look like it has a password in it":
// a provider path token (`/live/USER/PASS/123.ts`) is a credential as surely
// as a query parameter is, which is why rule 5 treats whole URLs as secrets
// rather than trying to find the secret inside one.
//
// And the write that must NEVER be gated is the one that takes the URL OUT.
// `removeSource` persists ("", ""), and if that could be refused because the
// file is exposed then a user whose shell.json is 0644 could not remove the
// credential that is sitting in it -- the fix would hold the defect in place.
function persistCarriesSecret(playlistUrl, epgUrl) {
  return str(playlistUrl).trim() !== "" || str(epgUrl).trim() !== ""
}

// Three answers, because QML cannot block on a Process.
//
//   persist  the file is known private, or this write carries no secret
//   refuse   the file is known NOT private and could not be made private
//   defer    no answer yet -- hold the write, do not guess either way
//
// `defer` exists for one window: the shield runs at service start, and a
// persist that arrives before its first exit must neither write blind (which
// is the defect) nor fail the user (which would be a refusal we cannot
// justify, since the file may well be fine). After the first exit the state
// is always private or exposed, so this answer is reachable only in that
// window; see Service.qml's pendingPersist for what holding it means.
function configShieldDecision(state, playlistUrl, epgUrl) {
  if (!persistCarriesSecret(playlistUrl, epgUrl)) return CONFIG_PERSIST
  var s = str(state)
  if (s === CONFIG_SHIELD_PRIVATE) return CONFIG_PERSIST
  // No file means no credential in it. The host creates it on this write and
  // the re-arm after every write tightens it; the residual is that one gap,
  // which is stated in ARCHITECTURE and is smaller than refusing every save
  // on a machine that has no user config yet.
  if (s === CONFIG_SHIELD_ABSENT) return CONFIG_PERSIST
  if (s === CONFIG_SHIELD_EXPOSED) return CONFIG_REFUSE
  return CONFIG_DEFER
}

// D-SINK-19. The gate's question, asked of the ENTRY about to be written
// instead of of two argument names.
//
// Why this exists rather than a call that passes two empty strings. The
// plugin no longer writes a URL into the host's file at all -- `ownedEntryPatch`
// names `sourceKey` and `showLogos`, and `entryWith` strips the retired keys --
// so the gate above would never fire again on any shipping path, and a gate
// that cannot fire is a gate nobody notices breaking (rule 14). Asking the
// patch means the answer comes back REFUSE the moment a URL-bearing key is
// written again, whoever writes it and whatever they call it.
//
// IS A SOURCE KEY A SECRET? No, and this is the risk that decision accepts.
// A key is `fnv1a32` of the normalized playlist URL: eight hex characters,
// 32 bits, which cannot carry a URL back. What it can do is CONFIRM a guess
// -- anyone who can read `shell.json` may hash a candidate URL and see
// whether it matches -- so a reader who already holds a provider URL learns
// that this user has that account. That is a real loss, it is not zero, and
// it is smaller by a category than the credential itself, which is what used
// to be in the file. ACCEPTED, because the alternative is worse: gating the
// key write would let an exposed file refuse the very write that TAKES THE
// URL OUT, which is the trap `persistCarriesSecret` already documents one
// function above. The exposure is not "closed"; it is reduced from the
// credential to a 32-bit check on a guess.
function entryShieldDecision(state, patch) {
  var p = patch || {}
  return configShieldDecision(state, p.playlistUrl, p.epgUrl)
}

function seqArg(seq) {
  var n = Math.floor(Number(seq))
  return String(isFinite(n) && n > 0 ? n : 0)
}

// One `--mpv-arg=<token>` member per user token. The attached form is not
// cosmetic: argparse refuses an option-looking VALUE, so the separated form
// `--mpv-arg --profile=low-latency` dies with "expected one argument" - which
// is every realistic token, since mpv options all start with "--" (verified
// against python 3.14's argparse). Attached, each token is still exactly one
// argv member, never joined with another and never split.
function mpvArgArgv(mpvArgs) {
  var list = asList(mpvArgs)
  var out = []
  for (var i = 0; i < list.length; i++) {
    var token = str(list[i])
    if (token === "") continue
    out.push("--mpv-arg=" + token)
  }
  return out
}

function playerSessionArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid) {
  var argv = ["--socket", str(socket), "--cache-dir", str(cacheDir), "--id", str(id), "--seq", seqArg(seq)]
  if (str(scope) !== "") argv = argv.concat(["--scope", str(scope)])
  var when = Math.floor(Number(since))
  if (isFinite(when) && when > 0) argv = argv.concat(["--since", String(when)])
  var pid = Math.floor(Number(ownerPid))
  if (isFinite(pid) && pid > 0) argv = argv.concat(["--owner-pid", String(pid)])
  return argv.concat(mpvArgArgv(mpvArgs))
}

// `ownerPid` is optional and additive: passing Quickshell.processId here
// claims the player for this shell at the same moment it starts playing, so
// the plugin-removal case (PO-2 / PLAYER-LIVE-04) has a claim to check even
// when the service never ran a probe that found anything.
function playerStartArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid) {
  return ["player", "start"].concat(playerSessionArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid))
}

// `from` picks the first rung: "" or "quit" starts at `quit` over IPC,
// "term" skips straight to SIGTERM (the health verdict, where IPC is by
// definition not answering), "kill" to SIGKILL.
function playerStopArgv(socket, seq, from) {
  var argv = ["player", "stop", "--socket", str(socket), "--seq", seqArg(seq)]
  var rung = str(from)
  if (rung === "quit" || rung === "term" || rung === "kill") argv = argv.concat(["--from", rung])
  return argv
}

function playerRestartArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, from, ownerPid) {
  var argv = ["player", "restart"].concat(playerSessionArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid))
  var rung = str(from)
  if (rung === "quit" || rung === "term" || rung === "kill") argv = argv.concat(["--from", rung])
  return argv
}

// PAUSE LIVE TV (2026-09-24). mpv keeps filling its cache while paused, so
// resuming continues from the moment it was pressed and the viewer is then
// behind live. Going back to BEFORE the keypress is `playerSeekArgv` (M5-01,
// 2026-10-03), which moves inside the same cache: an earlier version of this
// comment said "exactly ONE of 22 channels reported itself seekable, so
// there is no going back", a true reading of `seekable` with a false
// conclusion attached -- 31 of 32 channels rewound 20 s with that property
// reading false, because `demuxer-cache-state.seekable-ranges` is the one
// that decides (SPIKE-LIVE-REWIND.md, dev branch). The bound of a pause is mpv's
// 150 MiB forward quota: 315 s measured on a ~3.8 Mbps stream, less on a
// fatter one, with or without history behind it; a long pause then eats the
// rewind window one second per paused second (11.2).
//
// `state` is "on", "off" or "toggle"; anything else is a toggle, because a
// key that means "pause" must never be able to mean "start playing".
function playerPauseArgv(socket, state) {
  var want = str(state)
  if (want !== "on" && want !== "off") want = "toggle"
  return ["player", "pause", "--socket", str(socket), "--state", want]
}

// ------------------------------------------------------------ notifications

// argv for omarchy-notification-send per UX 6.4. Bodies never carry a URL.
// Options come first, then the constant headline, then the body. The
// wrapper (busctl-based) takes the body positionally unless it looks like
// one of its own flags (`--urgency=...`, `-g`, ...), so the body is built to
// never start with "-": the playlist-controlled name is quoted with the
// typographic quotes and cleaned of leading dashes (S-04).
function notifyArgv(event, params) {
  var p = params || {}
  var spec = null
  var name = cleanName(p.name) || "Channel"
  var reason = scrubUrls(str(p.reason))
  if (event === "streamFailed") {
    spec = { title: "Stream failed", body: QUOTE_OPEN + name + QUOTE_CLOSE + " did not play" + (reason !== "" ? SEP + reason : ""), glyph: GLYPHS.tvOff, urgency: "normal", id: NOTIFY_IDS.streamFailed }
  } else if (event === "playlistRefreshed") {
    spec = { title: "Playlist refreshed", body: pluralChannels(p.channelCount) + " in " + formatCount(p.groupCount) + (Number(p.groupCount) === 1 ? " group" : " groups"), glyph: GLYPHS.refresh, urgency: "low", id: NOTIFY_IDS.playlistRefreshed }
  } else if (event === "playlistError") {
    var tail = p.cachedAt ? "Using cached copy from " + str(p.cachedAt) + "." : "Open the guide for details."
    spec = { title: "Playlist error", body: "Could not fetch the playlist (" + (reason || "unknown error") + "). " + tail, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.playlistError }
  } else if (event === "epgError") {
    spec = { title: "Guide data error", body: "Could not fetch the EPG (" + (reason || "unknown error") + "). Channels still work.", glyph: GLYPHS.alert, urgency: "low", id: NOTIFY_IDS.epgError }
  } else if (event === "mpvMissing") {
    spec = { title: "mpv not found", body: "Install mpv to play channels.", glyph: GLYPHS.tvOff, urgency: "critical", id: NOTIFY_IDS.mpvMissing }
  } else if (event === "entryInputRefused") {
    // R21b: the text is Model.entryInputNotice's and nothing else, so the
    // notification, the console line and the test read one sentence. It
    // takes a setting NAME and a reason, never a value (rule 5).
    var notice = entryInputNotice(p.setting, p.reason)
    spec = { title: notice.title, body: notice.body, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.entryInputRefused }
  } else if (event === "stateUnreadable") {
    // R22a: Model.stateUnreadableNotice's sentence and nothing else, for the
    // same reason as the refusal above. A reason and a PATH, never a URL.
    // R27e: and the mid-session title when the block began after a load.
    var told = stateUnreadableNotice(p.reason, p.path, p.midSession === true)
    spec = { title: told.title, body: told.body, glyph: GLYPHS.alert, urgency: "critical", id: NOTIFY_IDS.stateUnreadable }
  } else if (event === "mergeDropped") {
    // R25b: Model.mergeDropNotice's sentence and nothing else -- counts and
    // caps, never a URL, a label, a query or a group name.
    var dropped = mergeDropNotice(p.dropped)
    if (dropped) spec = { title: dropped.title, body: dropped.body, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.mergeDropped }
  }
  if (!spec) return null
  return ["omarchy-notification-send", "--app-name", "IPTV", "-u", spec.urgency, "-g", spec.glyph, "-r", String(spec.id), spec.title, spec.body]
}

// ------------------------------------------------------------ privacy

// "scheme://host" for http(s) URLs, "local file" for paths, "" otherwise.
// Never returns path, query or userinfo (credentials live there).
function sourceLabel(url) {
  var text = str(url).replace(/^\s+|\s+$/g, "")
  if (text === "") return ""
  if (/^file:/i.test(text)) return "local file"
  // D-SINK-1's authority rule, which this spelling did not get when
  // redactUrls got it: userinfo runs to the LAST `@` of the authority
  // (RFC 3986) and the host group excludes `@` entirely. With the old
  // `(?:[^@\/\s]*@)?([^\/\s?#:]+)` pair, `http://user:p@ss@host/x` labelled
  // itself `http://ss@host` -- the password TAIL in the host position, which
  // is the defect redactUrls was fixed for. Both halves are needed: either
  // alone still leaks. M4-01 made this reachable from a remote party, because
  // resolveEpgUrl publishes `hostOf` over a `url-tvg` the PLAYLIST declared.
  var m = text.match(/^([a-z][a-z0-9+.-]*):\/\/(?:[^\/\s]*@)?([^\/\s?#:@]+)(?::\d+)?/i)
  if (m) {
    var scheme = m[1].toLowerCase()
    if (scheme === "file") return "local file"
    return scheme + "://" + m[2]
  }
  if (text.charAt(0) === "/" || text.charAt(0) === "~") return "local file"
  return "unknown source"
}

function hostOf(url) {
  var label = sourceLabel(url)
  var at = label.indexOf("://")
  return at === -1 ? label : label.substring(at + 3)
}

// Replace every `scheme://...` in free text by its host alone (R12, D-QA-01):
// userinfo, port, path and query are gone. Applied at every sink that can
// carry mpv or helper output (notifications, lastError, console, tooltips).
// D-SINK-1. The userinfo group used to be `(?:[^@\/\s]*@)?`, which cannot span
// a SECOND `@` -- while the host group happily accepted one. A provider whose
// password contains an un-encoded `@` therefore had its password TAIL survive
// into the host position and out through a desktop notification. RFC 3986 puts
// userinfo before the LAST `@` of the authority, so the group now runs to it
// and the host excludes `@` entirely. Both changes are needed: either alone
// still leaks.
//
// F-SINK-11. The scan is ANCHORED ON "://" and never re-reads a run of
// scheme-legal characters, so the cost is linear in the length of the text.
//
// What was wrong. The pattern was
// `/[a-z][a-z0-9+.-]*:\/\/(?:[^\/\s]*@)?([^\/\s?#:@]*)[^\s]*/gi`. On a run of
// scheme-legal characters the engine consumed the whole run from EVERY start
// position and backtracked out of it, so the cost was quadratic. Measured on
// node v26.8.1 over a run of letters: 2.5 ms at 1,000 characters, 40.1 at
// 5,000, 159.0 at 10,000, 659.3 at 20,000, 2578.5 at 40,000. After this
// change, same vector and same machine: 0.001 ms at every one of those five
// sizes. The guarded entry point `sinkText` does NOT cover the case that
// matters: a long run in the same string as a URL still contains "://", so it
// still paid the whole cost -- "http://u:p@h.test/x " followed by 40,000
// letters cost 2575.8 ms through this function and 0.001 ms after this change.
// The slowest vector that remains is a run of letters ending in a real URL,
// where the whole run is the "scheme" the old pattern also swallowed: 0.050 /
// 0.034 / 0.049 / 0.094 / 0.195 ms over the same five sizes. IT IS ALSO THE
// ONE VECTOR THIS CHANGE MAKES SLOWER, and saying so is the point: the old
// pattern consumed that run in the engine and this walks it in JS, 0.058 ms
// against 0.191 at 40,000 characters and 1.5 ms against 8.6 at 1 MiB. Linear
// either way. The trade is three orders of magnitude on the shapes that were
// quadratic for a factor of five on the one that never was.
//
// Why it is the same answer, rather than a narrower pattern. The old pattern
// could only match where a `://` follows a run of scheme-legal characters
// beginning with a letter, and `:` and `/` are not scheme-legal, so the greedy
// run always ended EXACTLY at that `://`: there was never a shorter candidate
// to backtrack to. So "walk back from each `://` over the scheme-legal run,
// then forward to the first letter in it" picks the same leftmost start the
// engine picked, and the authority rules below (userinfo to the LAST `@`
// before the first `/`, host excluding `@`) are the old groups transcribed
// character class by character class. The node suite (dev branch) drives the
// OLD pattern as an oracle over the shared fixture and thousands of generated
// strings and asserts the two agree character for character, so the claim is
// checked rather than argued.
//
// This makes the caps that currently stand in front of every sink CHEAP, not
// unnecessary. The caps are still the reason a 64 MiB description cannot
// reach a renderer at all; this only stops redaction itself being the thing
// that stalls when one does.
var SPACE_RE = /\s/

// `\s` exactly as the old pattern's `[^\s]` and `[^\/\s]` read it: the ASCII
// cases without a regex call, everything above it by asking the engine, so
// U+00A0, the Zs block, U+2028/9 and U+FEFF are not quietly reclassified.
function isSpaceAt(s, i) {
  var c = s.charCodeAt(i)
  if (c === 32 || (c >= 9 && c <= 13)) return true
  if (c < 128) return false
  return SPACE_RE.test(s.charAt(i))
}

// `[a-z0-9+.-]` under the `i` flag.
function isSchemeRestCode(c) {
  return (c >= 97 && c <= 122) || (c >= 65 && c <= 90) || (c >= 48 && c <= 57)
    || c === 43 || c === 46 || c === 45
}

// `[a-z]` under the `i` flag: the first character of a scheme.
function isLetterCode(c) {
  return (c >= 97 && c <= 122) || (c >= 65 && c <= 90)
}

function redactUrls(text) {
  var s = str(text)
  var j = s.indexOf("://")
  if (j === -1) return s               // the old pattern cannot match: same answer
  var n = s.length
  var out = ""
  var copied = 0                       // everything before this is already in `out`
  // The engine's lastIndex: no match may start before it. `j` is only ever
  // searched from `resume` or from a position already at or past it, so there
  // is no `j < resume` case to guard -- and a guard for a case that cannot
  // happen is a branch no test can go red for.
  var resume = 0
  while (j !== -1) {
    // The leftmost start the old pattern would have taken for this "://":
    // back over the scheme-legal run, then forward to its first letter.
    var b = j
    while (b > resume && isSchemeRestCode(s.charCodeAt(b - 1))) b--
    var p = b
    while (p < j && !isLetterCode(s.charCodeAt(p))) p++
    if (p >= j) {
      // No letter in the run, so the pattern has no match ending here.
      // j+1 and j+2 cannot begin a "://" of their own; +1 keeps that from
      // being load-bearing.
      j = s.indexOf("://", j + 1)
      continue
    }
    var end = j + 3                    // the old `[^\s]*` tail
    while (end < n && !isSpaceAt(s, end)) end++
    var slash = j + 3                  // `[^\/\s]*` stops at the first `/`
    while (slash < end && s.charCodeAt(slash) !== 47) slash++
    // D-SINK-1: userinfo runs to the LAST `@` of the authority (RFC 3986),
    // which is what the old `(?:[^\/\s]*@)?` resolved to by backtracking.
    var h0 = j + 3
    for (var k = j + 3; k < slash; k++) if (s.charCodeAt(k) === 64) h0 = k + 1
    // `([^\/\s?#:@]*)`. The `@` in that class was half of D-SINK-1 and it is
    // REDUNDANT here, deliberately: `h0` is already past the last `@` before
    // the first `/` and the scan stops at that `/`, so nothing in range can be
    // one. It stayed because the class is the old group transcribed and
    // because a redactor is the wrong place to shave a branch -- but it cannot
    // be observed, so no test can go red for it (rule 14) and the line above
    // is what actually carries the rule. A mutation that breaks `h0` is caught;
    // a mutation that drops `c === 64` is not, and that is a fact about this
    // code rather than a gap in the suite.
    var h1 = h0
    while (h1 < end) {
      var c = s.charCodeAt(h1)
      if (c === 47 || c === 63 || c === 35 || c === 58 || c === 64) break
      h1++
    }
    var host = s.substring(h0, h1)
    out += s.substring(copied, p) + (host !== "" ? host : "[url]")
    copied = end
    resume = end
    j = s.indexOf("://", resume)
  }
  return out + s.substring(copied)
}

// Older name kept for callers; same behaviour.
function scrubUrls(text) {
  return redactUrls(text)
}

// F-SINK-10. Provider-controlled text on its way to a guide-text or
// accessibility sink, redacted exactly as redactUrls redacts it and at a
// linear cost.
//
// WHY THIS EXISTS AS ITS OWN NAME rather than `redactUrls` at each call site.
// It was written because redactUrls was QUADRATIC in a run of scheme-legal
// characters, and these sinks run per instantiated row, on every clock tick
// and on every keystroke in search mode -- the one place in this plugin where
// a 0.6 ms call is not free. F-SINK-11 removed that reason: redactUrls is
// linear now and takes this very exit itself, so what is left here is one
// `indexOf` instead of one call, and the NAME, which is the part that was
// always load-bearing -- it is how the four composers below cannot drift
// about where redaction happens. The exit is EXACT and not an approximation:
// redactUrls cannot rewrite text with no "://" in it, and the node suite
// asserts the two agree over every input it is given.
//
// WHY AT THE SINK and not at one caller. The strings these sinks compose come
// from an XMLTV programme title and an M3U channel name, both written by the
// provider. Until M4-01 the matcher matched 0 of 1,453 channels on the
// owner's install, so the row's now/next title was empty on every row and the
// gap was theoretical; M4-01 made it 227 channels of provider-written titles.
// Redacting in the composers (rowDetail, rowAccessibleName, formatEpgLine)
// AND at the epgFields boundary that feeds them means a caller that hands a
